import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"37、【家人】 离下巽上","description":"周易尚氏学 - 37、【家人】 离下巽上","frontmatter":{"title":"37、【家人】 离下巽上","description":"周易尚氏学 - 37、【家人】 离下巽上"},"headers":[],"relativePath":"zh/classics/shangshi/042.md","filePath":"zh/classics/shangshi/042.md"}'),h={name:"zh/classics/shangshi/042.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_37、【家人】-离下巽上" tabindex="-1">37、【家人】 离下巽上 <a class="header-anchor" href="#_37、【家人】-离下巽上" aria-label="Permalink to “37、【家人】 离下巽上”">​</a></h1><p>归藏曰散家人。卦以一阳一阴。散处于卦内。又上卦巽风。下卦火炎上。均有敬意。故以为名乎。马融曰。家人以女为奥主。长女中女。各得其正。故曰利女贞。然象传曰。男正位乎外。似家人兼男女言。特女尤利耳。又考太玄拟家人为居。云踞肤赫赫。为物城郭。万物咸宅。是以家人初上爻皆阳。故曰肤。曰城郭。而人宅其中。故曰家人也。义似较各家为优。二四得正。承阳有应。故利于女子之占也。</p><p>彖曰。家人女正位子内。男正位乎外。男女正。天地之大义也。家人有严君焉。父母之谓也。父父。子子。兄兄。弟弟。夫夫。妇妇。而家道正。正家而天下定矣。</p><p>女正位乎内谓二。男正位乎外谓五。二五者夫妇。即天地也。即父母也。父母皆得正位。故曰严君。严君者尊也。卦下五爻皆得正。故曰父父。子子。兄兄。弟弟。夫夫。妇妇。初震交。震为子。为兄。为夫。三艮爻互坎。坎艮皆为弟。巽为妇。父子兄弟夫妇皆得正。则家正。家齐则国治。故曰天下定。</p><p>象曰。风自火出。家人。君子以言有物。而行有恒。</p><p>巽木生火。火动生风。故曰风自火出。物。孔疏云事也。按周礼地官。司门几出人之不物者。注。衣服视瞻。不与众同。及所操物。不如品式者。然则不物即违常。即不法也。言有物者。即言不离乎经常也。</p><p>初九。闲有家。悔亡。</p><p>释文。马云闲阑也。防也。离中虚外坚。故离有闲义。即太玄所谓为物城郭也。能闭其家。故侮亡也。荀郑训闲为闲习。似非。</p><h3 id="象曰。闲有家。志未变也。" tabindex="-1">象曰。闲有家。志未变也。 <a class="header-anchor" href="#象曰。闲有家。志未变也。" aria-label="Permalink to “象曰。闲有家。志未变也。”">​</a></h3><p>初应在四。四体坎。坎为志。志未变者。言初与四为正应。无敢或渝。所谓行有恒而家道正也。其以遂为说者。皆因不得解而穿凿也。</p><p>六二。无攸遂。在中馈。贞吉。</p><p>礼月令百事乃遂。注遂犹成也。公羊传桓八年。大夫无遂事。注遂专事也。坤道无成。六二应五承三。顺以类可矣。不必专事也。故曰无攸遂。六二得中。故曰在中馈。馈饷也。周礼天官。膳夫掌王之馈。注进食于尊曰馈。在中馈者。言道顺从。无敢专事。职供中馈。酒食是议也。贞吉者。卜问吉也。</p><h3 id="象曰。六二之吉。顺以巽也。顺以巽。言承三应五也。" tabindex="-1">象曰。六二之吉。顺以巽也。顺以巽。言承三应五也。 <a class="header-anchor" href="#象曰。六二之吉。顺以巽也。顺以巽。言承三应五也。" aria-label="Permalink to “象曰。六二之吉。顺以巽也。顺以巽。言承三应五也。”">​</a></h3><p>九三。家人高高（左口）。 悔历吉。妇子嘻嘻。终吝。</p><p>释文。高高（左口）。马云悦乐自得儿。荀作确确。按离外坚。荀读是也。嘻嘻郑云骄佚笑乐之意。然同在一爻。吉吝不同者。盖三居离上。离外坚。有坚确自守。安不忘危之意。故曰家人高高（左口）。高高（左口）则守正安常。故厉而古也。而三前临巽风。巽为妇。为进退。为躁动。为声应。故曰妇子嘻嘻。嘻嘻则悦而淫矣。故曰终吝。高高（左口）之象下取离。嘻嘻之象上取巽。诚以同此一爻。或吉或吝。必有其故。而光儒无言者。探测如此。</p><h3 id="象曰。家人高高-左口-。未失也。妇子嘻嘻。失家节也。" tabindex="-1">象曰。家人高高（左口）。未失也。妇子嘻嘻。失家节也。 <a class="header-anchor" href="#象曰。家人高高-左口-。未失也。妇子嘻嘻。失家节也。" aria-label="Permalink to “象曰。家人高高（左口）。未失也。妇子嘻嘻。失家节也。”">​</a></h3><p>失佚古通。未佚者言不敢放逸也。若嘻嘻则淫佚而不中节矣。故曰失家节。失。下读得之失。上读佚。以与节韵。</p><p>六四。富家大吉。</p><p>乾为富。四承重阳。当位有应。体坎。坎为室家。故曰富家大吉。凡上卦为巽。四当位无不吉者。如小言观益巽涣中孚。六四皆吉。谁不当位者。虽临重阳。不尽吉也。此易例也。虞翻旨命三变成艮。最为害理。三当位。胡为使失正哉。</p><h3 id="象曰。富家大吉。顺在位也。" tabindex="-1">象曰。富家大吉。顺在位也。 <a class="header-anchor" href="#象曰。富家大吉。顺在位也。" aria-label="Permalink to “象曰。富家大吉。顺在位也。”">​</a></h3><p>言富之故。以顺阳也。五得位。故曰顺在位。</p><p>九五。王假有家。勿恤。吉。</p><p>五天子。故曰王。假释文更白反。注至也。案虞书。格子上下。传。格至也。是王弼陆德明皆读假为格。与萃之王假有庙同。王假有庙。言王以至诚感神明。王假有家。言王以至德威格家人。无有不正。故无所忧而吉也。</p><h3 id="象曰。王假有家。交相爱也。" tabindex="-1">象曰。王假有家。交相爱也。 <a class="header-anchor" href="#象曰。王假有家。交相爱也。" aria-label="Permalink to “象曰。王假有家。交相爱也。”">​</a></h3><p>交相爱。谓二五交孚。即释格义。诸家皆释假为大。与交相爱之义相去甚远。故唯王注为得也。</p><p>上九。有孚。威如。终吉。</p><p>上九居家之上。为全家所戴。故曰有孚。曰威如。上居卦终。故曰终吉。</p><h3 id="象曰。威如之吉。反身之谓也。" tabindex="-1">象曰。威如之吉。反身之谓也。 <a class="header-anchor" href="#象曰。威如之吉。反身之谓也。" aria-label="Permalink to “象曰。威如之吉。反身之谓也。”">​</a></h3><p>巽究成震。震为威。言震巽相反复。故曰反身。虞翻命三变成阴。以说反身。三当位。胡能使变。乃惠栋不知其强说。谓蹇上六志在内为反身。夫蹇三上皆当位有应与。若家人则三上皆阳。艮传所谓敌应也。上胡能反三哉。</p>',29)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
